'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var factory = require( './../lib/factory.js' );


// FIXTURES //

var data = require( './fixtures/python/data.json' );
var p = data.p;
var sigma = data.sigma;
var expected = data.expected;


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'factory returns a function', function test( t ) {
	var q = factory( 1.0 );
	t.strictEqual( typeof q, 'function', 'returns expected value' );
	t.end();
});

tape( 'if sigma is NaN or < 0, returned function always returns NaN', function test( t ) {
	var q;

	q = factory( NaN );
	t.ok( isnan( q( 0.5 ) ), 'sigma NaN' );

	q = factory( -1.0 );
	t.ok( isnan( q( 0.5 ) ), 'sigma < 0' );

	t.end();
});

tape( 'if sigma = 0, quantile always returns 0', function test( t ) {
	var q = factory( 0.0 );
	t.strictEqual( q( 0.0 ), 0.0 );
	t.strictEqual( q( 0.5 ), 0.0 );
	t.strictEqual( q( 1.0 ), 0.0 );
	t.end();
});

tape( 'if p < 0, p > 1, or p is NaN, quantile returns NaN', function test( t ) {
	var q = factory( 1.0 );

	t.ok( isnan( q( -0.1 ) ), 'p < 0' );
	t.ok( isnan( q( 1.1 ) ), 'p > 1' );
	t.ok( isnan( q( NaN ) ), 'p NaN' );

	t.end();
});

tape( 'p = 1 returns +Infinity', function test( t ) {
	var q = factory( 1.0 );
	t.strictEqual( q( 1.0 ), PINF, 'returns +Infinity' );
	t.end();
});

tape( 'the factory evaluates the Half-normal quantile correctly', function test( t ) {
	var y;
	var q;
	var i;

	for ( i = 0; i < p.length; i++ ) {
		q = factory( sigma[i] );
		if ( expected[i] !== null ) {
			y = q( p[i] );
			if ( y === expected[i] ) {
				t.strictEqual( y, expected[i], 'p: '+p[i]+', sigma: '+sigma[i]+', y: '+y+', expected: '+expected[i] );
			} else {
				t.ok( isAlmostSameValue( y, expected[ i ], 40.0 ), 'within tolerance. p: '+p[ i ]+'. sigma: '+sigma[ i ]+'. y: '+y+'. expected: '+expected[ i ]+'.' );
			}
		}
	}
	t.end();
});
